const release={"schemaVersion":"1.2.0","version":"6.0.0","buildDate":"2026-08-05","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":1,"title":"Number and Algebra"},"lesson":{"number":"1.5","slug":"exponent-laws-logarithms","title":"Exponent Laws and Logarithms","subtitle":"Build exact exponent structure, solve unknown-exponent equations, invert multiplicative models with logarithms and interpret logarithmic scales.","syllabus_focus":"Current AI SL Number and Algebra — laws of exponents, rational powers, exponential equations, introduction to logarithms with bases 10 and e, change of base, modelling and logarithmic scales.","skill_keys":["IBAI.U1.ALGEBRA","IBAI.U1.MODELING"],"objectives":["Simplify integer, zero, negative and rational exponents exactly and state necessary restrictions.","Solve exponential equations using common bases, substitution, logarithms or graph intersection as appropriate.","Interpret logarithms as inverse exponents and move fluently between exponential and logarithmic forms.","Evaluate logarithms using exact structure and change of base.","Apply logarithms to growth, decay, threshold and logarithmic-scale contexts.","Verify technology output and interpret domain, units, discrete timing, assumptions and limitations."],"vocab":["base","exponent","zero exponent","negative exponent","rational exponent","common base","logarithm","argument","common logarithm","natural logarithm","change of base","logarithmic scale","threshold"],"technology":"Use exact structure before technology. For non-integer solutions, show the isolated exponential equation and logarithmic calculation, then verify by substitution or graph intersection. Preserve guard digits and interpret continuous versus discrete time.","source_basis":["Pearson Mathematics: Applications and Interpretation SL — exponent laws, exponential equations and logarithmic inversion","Christos Nikolaidis MAI 1.2–1.3 — exponents, systems and current-course logarithm task patterns","Supplied Topic 1A number and algebra reference material","Existing ECHS Unit 1 platform architecture and authenticated mastery integration"],"transition":"This lesson supports cohorts assessed through the current syllabus cycle. Its course-transition note remains explicit because logarithm scope changes in the revised course first assessed in 2029."}};
